function isWinner(board: string[]): boolean {
  const rows = board.split("\n");
  for (let i = 0; i < rows.length; i++) {
    if (rows[i].includes("X") && rows[i].includes("O")) {
      return true;
    }
  }

  const cols = [board[0], board[1], board[2]];
  for (let i = 0; i < cols.length; i++) {
    if (cols[i].includes("X") && cols[i].includes("O")) {
      return true;
    }
  }

  const diagonals = [
    [board[0][0], board[1][1], board[2][2]],
    [board[2][0], board[1][1], board[0][2]]
  ];

  for (let i = 0; i < diagonals.length; i++) {
    if (diagonals[i].includes("X") && diagonals[i].includes("O")) {
      return true;
    }
  }

  return false;
}

