function gridPathfinding(grid: number[][], blocked: boolean[][]): number {
    const rows = grid.length;
    const cols = grid[0].length;

    // Initialize the DP table with -1 to indicate unvisited cells
    let dpTable: number[][] = Array.from({ length: rows }, () => Array(cols).fill(-1));

    // Base case: if a cell is blocked, set its value to 0
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            if (blocked[i][j]) {
                dpTable[i][j] = 0;
            }
        }
    }

    // Fill the DP table
    for (let i = 1; i < rows; i++) {
        for (let j = 1; j < cols; j++) {
            if (!blocked[i - 1][j]) {
                dpTable[i][j] = Math.max(dpTable[i - 1][j], dpTable[i][j - 1] + grid[i - 1][j]);
            }
        }
    }

    // The result is the value at the bottom-right cell
    return dpTable[rows - 1][cols - 1];
}

export function main(): null {
    const blocked = [
        [false, false, true],
        [true, true, false],
        [false, false, false]
    ];

    const pathCount = gridPathfinding(blocked, blocked);
